#!/usr/bin/env bash
# READ ONLY: recent QA plan lines that have a net price (priced OK) vs not
sf data query --query "SELECT Quote.QuoteNumber, Product2.ProductCode, ProductSellingModel.Name, CurrencyIsoCode, BillingFrequency, Billing_Frequency_Value__c, Location_count__c, SubscriptionTerm, Quantity, ListPrice, NetUnitPrice, CreatedBy.Name, LastModifiedDate FROM QuoteLineItem WHERE Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT') ORDER BY LastModifiedDate DESC LIMIT 25" --target-org target --json | jq -r '.result.records[] | [.Quote.QuoteNumber, .Product2.ProductCode, .ProductSellingModel.Name, .CurrencyIsoCode, .BillingFrequency, .Billing_Frequency_Value__c, .Location_count__c, .SubscriptionTerm, .Quantity, .ListPrice, .NetUnitPrice, .CreatedBy.Name, .LastModifiedDate] | map(tostring) | join(" | ")'
